css:
/* Costaria RFP — Corporate / Executive theme */
.rfp-sim-container {
    padding: 28px;
    background: #eef1f6;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}

/* Header */
.rfp-sim-container .rfp-sim-header {
    background: linear-gradient(135deg, #0f2747 0%, #1a3866 100%);
    color: #f4f6fa;
    border-radius: 4px;
    padding: 28px 32px;
    margin-bottom: 24px;
    border-left: 6px solid #c9a961;
    box-shadow: 0 4px 18px rgba(15,39,71,0.18);
}
.rfp-sim-container .rfp-sim-eyebrow {
    color: #c9a961;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    margin-bottom: 10px;
    font-weight: 600;
}
.rfp-sim-container .rfp-sim-title {
    font-size: 1.7rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: 0.01em;
    color: #ffffff;
}
.rfp-sim-container .rfp-sim-subtitle {
    color: #b8c3d6;
    font-size: 0.95rem;
    font-weight: 400;
    margin-bottom: 14px;
}
.rfp-sim-container .rfp-sim-period {
    display: inline-block;
    background: rgba(201,169,97,0.15);
    color: #c9a961;
    padding: 6px 14px;
    border-radius: 3px;
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

/* KPI grid */
.rfp-sim-container .rfp-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.rfp-sim-container .rfp-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d8dfe9;
    border-top: 3px solid #1a3866;
    border-radius: 4px;
    padding: 18px 18px 16px 18px;
    transition: box-shadow 0.2s ease, transform 0.2s ease;
}
.rfp-sim-container .rfp-sim-kpi-card:hover {
    box-shadow: 0 6px 18px rgba(15,39,71,0.12);
    transform: translateY(-2px);
}
.rfp-sim-container .rfp-sim-kpi-accent {
    border-top-color: #c9a961;
    background: linear-gradient(180deg, #fffaf0 0%, #ffffff 50%);
}
.rfp-sim-container .rfp-sim-kpi-label {
    color: #5d6b80;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 600;
    margin-bottom: 8px;
}
.rfp-sim-container .rfp-sim-kpi-value {
    font-size: 1.8rem;
    font-weight: 700;
    color: #0f2747;
    line-height: 1.1;
}

/* Briefing card */
.rfp-sim-container .rfp-sim-briefing {
    background: #ffffff;
    border: 1px solid #d8dfe9;
    border-left: 4px solid #c9a961;
    border-radius: 4px;
    padding: 22px 26px;
    margin-bottom: 24px;
    box-shadow: 0 2px 10px rgba(15,39,71,0.06);
}
.rfp-sim-container .rfp-sim-briefing-title {
    font-size: 1.15rem;
    font-weight: 700;
    color: #0f2747;
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: 1px solid #e5e9f0;
}
.rfp-sim-container .rfp-sim-briefing-block {
    margin-bottom: 12px;
}
.rfp-sim-container .rfp-sim-briefing-block:last-child {
    margin-bottom: 0;
}
.rfp-sim-container .rfp-sim-briefing-h {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #846a26;
    font-weight: 700;
    margin-bottom: 5px;
}
.rfp-sim-container .rfp-sim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2d3a52;
}

/* Controls panel */
.rfp-sim-container .rfp-sim-controls {
    background: #ffffff;
    border: 1px solid #d8dfe9;
    border-radius: 4px;
    padding: 24px 26px;
    margin-bottom: 24px;
    box-shadow: 0 2px 10px rgba(15,39,71,0.06);
}
.rfp-sim-container .rfp-sim-controls h3 {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: #5d6b80;
    font-weight: 700;
    margin: 0 0 18px 0;
    padding-bottom: 10px;
    border-bottom: 1px solid #e5e9f0;
}
.rfp-sim-container .rfp-sim-panel {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 16px;
    margin-bottom: 18px;
}
.rfp-sim-container .rfp-sim-field {
    display: flex;
    flex-direction: column;
}
.rfp-sim-container .rfp-sim-field label {
    font-size: 0.78rem;
    font-weight: 600;
    color: #2d3a52;
    margin-bottom: 6px;
    letter-spacing: 0.02em;
}

/* Form controls — selects must be fully styled including option */
.rfp-sim-container select,
.rfp-sim-container input[type="number"],
.rfp-sim-container input[type="text"] {
    background: #f8fafc;
    border: 1px solid #c8d1de;
    color: #0f2747;
    border-radius: 3px;
    padding: 9px 12px;
    font-size: 0.92rem;
    font-family: inherit;
    width: 100%;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.rfp-sim-container select:focus,
.rfp-sim-container input:focus {
    outline: none;
    border-color: #1a3866;
    box-shadow: 0 0 0 3px rgba(26,56,102,0.12);
}
.rfp-sim-container select option {
    background: #ffffff;
    color: #0f2747;
}

/* Buttons */
.rfp-sim-container .rfp-sim-actions {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 8px;
}
.rfp-sim-container .rfp-sim-btn-primary {
    background: #0f2747;
    border: 1px solid #0f2747;
    color: #ffffff;
    padding: 10px 22px;
    font-weight: 600;
    font-size: 0.9rem;
    letter-spacing: 0.04em;
    border-radius: 3px;
    transition: background 0.18s ease, transform 0.12s ease;
}
.rfp-sim-container .rfp-sim-btn-primary:hover {
    background: #1a3866;
    border-color: #1a3866;
    color: #ffffff;
    transform: translateY(-1px);
}
.rfp-sim-container .rfp-sim-btn-undo {
    background: transparent;
    border: 1px solid #c8d1de;
    color: #5d6b80;
    padding: 8px 16px;
    font-size: 0.82rem;
    border-radius: 3px;
}
.rfp-sim-container .rfp-sim-btn-undo:hover {
    background: #f1f4f9;
    color: #0f2747;
    border-color: #5d6b80;
}

/* Charts */
.rfp-sim-container .rfp-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(380px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.rfp-sim-container .rfp-sim-chart {
    background: #ffffff;
    border: 1px solid #d8dfe9;
    border-radius: 4px;
    padding: 18px;
    height: 320px;
    box-shadow: 0 2px 10px rgba(15,39,71,0.06);
}

/* History table */
.rfp-sim-container .rfp-sim-history {
    background: #ffffff;
    border: 1px solid #d8dfe9;
    border-radius: 4px;
    padding: 18px 22px;
    box-shadow: 0 2px 10px rgba(15,39,71,0.06);
    overflow-x: auto;
}
.rfp-sim-container .rfp-sim-history table {
    width: 100%;
    margin: 0;
    color: #1a2744;
}
.rfp-sim-container .rfp-sim-history table thead th {
    background: #0f2747;
    color: #ffffff;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    padding: 10px 12px;
    border: none;
    text-align: left;
}
.rfp-sim-container .rfp-sim-history table tbody td {
    padding: 10px 12px;
    font-size: 0.88rem;
    border-bottom: 1px solid #eaeef4;
    color: #2d3a52;
}
.rfp-sim-container .rfp-sim-history table tbody tr:hover {
    background: #f8fafc;
}

/* Mobile */
@media (max-width: 768px) {
    .rfp-sim-container { padding: 16px; }
    .rfp-sim-container .rfp-sim-header { padding: 20px; }
    .rfp-sim-container .rfp-sim-title { font-size: 1.3rem; }
    .rfp-sim-container .rfp-sim-kpi-value { font-size: 1.4rem; }
    .rfp-sim-container .rfp-sim-panel { grid-template-columns: 1fr; }
    .rfp-sim-container .rfp-sim-charts { grid-template-columns: 1fr; }
    .rfp-sim-container .rfp-sim-actions { flex-direction: column; align-items: stretch; }
}
.rfp-sim-container select:focus-visible,
.rfp-sim-container button:focus-visible,
.rfp-sim-container a:focus-visible {
    outline: 3px solid #0f2747;
    outline-offset: 2px;
}

.rfp-sim-completion {
    background: #ffffff;
    border: 1px solid #d8dfe9;
    border-left: 4px solid #c9a961;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 24px;
}

.rfp-sim-completion-title {
    font-size: 1.1rem;
    font-weight: 700;
    color: #0f2747;
    margin: 0 0 10px 0;
}

.rfp-sim-completion-insights li {
    margin-bottom: 8px;
    line-height: 1.5;
}

@media (prefers-reduced-motion: reduce) {
    .rfp-sim-container *,
    .rfp-sim-container *::before,
    .rfp-sim-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* v1.2.0 round feedback and debrief */
.rfp-sim-container .rfp-sim-feedback {
    background: #ffffff;
    border: 1px solid #c8d0de;
    border-left: 6px solid #1a3866;
    border-radius: 4px;
    padding: 16px 20px;
    margin-bottom: 24px;
    color: #1f2a3d;
}
.rfp-sim-container .rfp-sim-feedback-title { font-weight: 700; color: #0f2747; margin-bottom: 8px; }
.rfp-sim-container .rfp-sim-feedback-line { margin: 0 0 6px 0; line-height: 1.5; }
.rfp-sim-completion .rfp-sim-completion-sub { margin: 6px 0; color: #1f2a3d; }
.rfp-sim-completion .rfp-sim-completion-turn { margin: 10px 0; padding: 10px 12px; border-left: 4px solid #7b683a; background: #f7f3e8; color: #1f2a3d; }
.rfp-sim-completion .rfp-sim-completion-questions { margin: 6px 0 0 18px; color: #1f2a3d; }
.rfp-sim-completion .rfp-sim-completion-questions li { margin-bottom: 4px; }
/* v1.2.0 no horizontal scroll at 360 px */
.rfp-sim-container .rfp-sim-chart { min-width: 0; max-width: 100%; box-sizing: border-box; }
.rfp-sim-container .rfp-sim-charts > * { min-width: 0; }
.rfp-sim-container .rfp-sim-history { max-width: 100%; overflow-x: auto; }
.rfp-sim-container select { max-width: 100%; }

