                currentPeriod: done ? this.ROUNDS.length + 1 : st.currentPeriod,
                decisions: st.decisions,
                domainState: st.domainState
            };
        }

        _readSelect(id) {
            var el = document.getElementById(id);
            if (!el) return null;
            var v = String(el.value == null ? '' : el.value);
            return v === '' ? null : v;
        }

        _warnIncomplete() {
            window.mySimulation.uiManager.showNotification(
                window.mySimulation.t('warn_pattern'), 'warning'
            );
            return false;
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod;

            var map = {
                1: { pattern: 'patternSelect', flipCondition: 'flipConditionSelect' },
                2: { tariff: 'tariffSelect', anchorTheme: 'themeSelect' },
                3: { integrityOption: 'integritySelect', monitor: 'monitorSelect', disclosure: 'disclosureSelect' },
                4: { gates: 'gatesSelect', escalation: 'escalationSelect' }
            }[period];
            if (!map) return false;

            var picked = {};
            for (var key in map) {
                if (!Object.prototype.hasOwnProperty.call(map, key)) continue;
                var v = this._readSelect(map[key]);
                if (v === null) return this._warnIncomplete();
                picked[key] = v;
            }
            for (var k in picked) {
                if (Object.prototype.hasOwnProperty.call(picked, k)) decisions[k] = picked[k];
            }
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return {
                period: r.period,
                roundScore: r.roundScore,
                pwin: r.pwin,
                expectedValue: r.expectedValue,
                integrityScore: r.integrityScore,
                disciplineScore: r.disciplineScore,
                airCover: r.airCover,
                carryOver: r.carryOver,
                nk: r.nk,
                ch: r.ch,
                overallScore: r.overallScore,
                score: r.overallScore
            };
        }

        _clamp(v) { return Math.max(0, Math.min(100, v)); }

        _composite(scores) {
            if (!scores || !scores.length) return 0;
            var total = 0;
            for (var i = 0; i < scores.length; i++) total += (Number(scores[i]) || 0);
            return this._clamp(Math.round((total / scores.length) * 10) / 10);
        }

        _band(composite) {
            var band = 'beginner';
            if (composite >= 60) band = 'competent';
            if (composite >= 75) band = 'disciplined';
            if (composite >= 82) band = 'senior';
            return band;
        }

        _bases() {
            return {
                A: { pwin: 22, margin: 38, ev: 12.5, integ: -8, disc: 12, score: 72, nk: 'n_p_a' },
                B: { pwin: 20, margin: 33, ev: 8.0, integ: 6, disc: 14, score: 70, nk: 'n_p_b' },
                C: { pwin: 35, margin: 14, ev: 10.0, integ: 8, disc: 10, score: 65, nk: 'n_p_c' },
                D: { pwin: 0, margin: 0, ev: 0, integ: 12, disc: 18, score: 68, nk: 'n_p_d' }
            };
        }

        _tariffs() {
            return {
                aggressive: { pwin: 5, margin: -16, score: 52, nk: 'n_t_aggressive' },
                mid: { pwin: 0, margin: 0, score: 78, nk: 'n_t_mid' },
                premium: { pwin: -8, margin: 13, score: 56, nk: 'n_t_premium' }
            };
        }

        _roundOutcome(p, ch, st) {
            var CARRY = 16;
            var MISMATCH = 24;
            var c1 = ch[1] || {};
            var c2 = ch[2] || {};
            var c3 = ch[3] || {};
            var c = ch[p] || {};
            var bases = this._bases();
            var tariffs = this._tariffs();
            var o = { score: 0, integ: 0, disc: 0, air: 0, carry: 0, nk: [] };
            var walked = c1.pattern === 'D';

            if (p === 1) {
                var b = bases[c.pattern] || bases.D;
                st.pwin = b.pwin; st.margin = b.margin; st.ev = b.ev;
                o.integ = b.integ; o.disc = b.disc; o.score = b.score;
                o.nk.push(b.nk);
                if (c.flipCondition && c.flipCondition !== 'none') {
                    o.disc += 8; o.score += 12; o.nk.push('n_flip_yes');
                } else {
                    o.score -= 18; o.nk.push('n_flip_no');
                }
            } else if (p === 2) {
                if (walked) {
                    o.score = 55; o.disc = 5; o.nk.push('n_r2_walked');
                } else {
                    var tf = tariffs[c.tariff] || tariffs.premium;
                    var pw = tf.pwin;
                    o.score = tf.score; o.nk.push(tf.nk);
                    var themePts = { '1': 14, '2': 9, '3': 5, '4': 3, '5': 4 };
                    var th = themePts[c.anchorTheme] !== undefined ? c.anchorTheme : '5';
                    o.score += themePts[th];
                    if (th === '1') pw += 2;
                    o.nk.push('n_th_' + th);
                    o.disc = 8; o.air = 5;
                    st.pwin = Math.max(0, st.pwin + pw);
                    st.margin = Math.max(0, st.margin + tf.margin);
                    st.ev = (st.pwin / 100) * st.margin + 8 - 2.4 - 1.5;
                }
            } else if (p === 3) {
                if (walked) {
                    o.score = 62; o.integ = 12; o.disc = 6; o.nk.push('n_r3_walked');
                } else {
                    var io = c.integrityOption;
                    var match = (io === c1.pattern);
                    var arch = { A: 32, B: 24, C: 20, D: 18 };
                    var archInteg = { A: 0, B: 8, C: 6, D: 14 };
                    if (arch[io] === undefined) io = 'D';
                    o.score += arch[io] - (match ? 0 : MISMATCH);
                    o.integ += archInteg[io];
                    o.nk.push('n_i_' + io.toLowerCase() + ((io === 'A' && !match) ? '_x' : ''));
                    if (!match) {
                        o.nk.push('n_reversal');
                        if (io === 'D') {
                            st.pwin = 0; st.margin = 0; st.ev = 0;
                        } else {
                            var nb = bases[io];
                            var t2 = tariffs[c2.tariff] || tariffs.mid;
                            st.pwin = Math.max(0, nb.pwin + t2.pwin);
                            st.margin = Math.max(0, nb.margin + t2.margin);
                            st.ev = (st.pwin / 100) * st.margin + 8 - 2.4 - 1.5;
                        }
                    }
                    if (c.monitor === 'thirdparty') {
                        o.integ += 20; o.score += 24; o.nk.push('n_m_thirdparty');
                    } else if (c.monitor === 'internal') {
                        o.integ -= 6; o.score -= 16; o.nk.push('n_m_internal');
                    } else {
                        o.integ -= 26; o.score -= 38; o.nk.push('n_m_none');
                    }
                    if (c.disclosure === 'full') {
                        o.integ += 8; o.score += 12; o.nk.push('n_d_full');
                    } else if (c.disclosure === 'partial') {
                        o.score -= 6; o.nk.push('n_d_partial');
                    } else {
                        o.integ -= 16; o.score -= 26; o.nk.push('n_d_none');
                    }
                    if (c2.tariff === 'aggressive') {
                        o.score -= CARRY; o.carry += CARRY; o.nk.push('n_carry_tariff');
                    }
                }
                o.disc += 10; o.air = 8;
            } else if (p === 4) {
                if (c.gates === '3') {
                    o.disc = 28; o.air = 32; o.score = 78; o.nk.push('n_g_3');
                } else if (c.gates === '2') {
                    o.disc = 14; o.air = 18; o.score = 58; o.nk.push('n_g_2');
                } else {
                    o.disc = 0; o.air = 6; o.score = 38; o.nk.push('n_g_1');
                }
                if (c.escalation === 'audit') {
                    o.integ += 14; o.air += 14; o.score += 18; o.nk.push('n_e_audit');
                } else if (c.escalation === 'ceo') {
                    o.air += 4; o.score -= 6; o.nk.push('n_e_ceo');
                } else {
                    o.integ -= 10; o.air -= 6; o.score -= 18; o.nk.push('n_e_team');
                }
                if (!c1.flipCondition || c1.flipCondition === 'none') {
                    o.score -= CARRY; o.carry += CARRY; o.air -= 10; o.nk.push('n_carry_flip');
                }
                if (!walked && c3.integrityOption && c3.integrityOption !== c1.pattern) {
                    o.score -= CARRY; o.carry += CARRY; o.nk.push('n_carry_reversal');
                }
            }
            o.score = this._clamp(o.score);
            return o;
        }

        _computeRound(state) {
            var d = state.decisions || {};
            var ds = state.domainState;
            var period = state.currentPeriod;
            var keys = {
                1: ['pattern', 'flipCondition'],
                2: ['tariff', 'anchorTheme'],
                3: ['integrityOption', 'monitor', 'disclosure'],
                4: ['gates', 'escalation']
            }[period] || [];

            var ch = {};
            var old = ds.choices || {};
            for (var q = 1; q < period; q++) { if (old[q]) ch[q] = old[q]; }
            var cur = {};
            for (var i = 0; i < keys.length; i++) cur[keys[i]] = d[keys[i]];
            ch[period] = cur;
            ds.choices = ch;
            if (period === 1) ds.bidPattern = cur.pattern;

            var st = { pwin: 22, margin: 38, ev: 12.5 };
            var integ = 70, disc = 50, air = 0;
            var pwinH = [], evH = [], scoreH = [], integH = [], discH = [], log = [];
            var last = null;
            for (var p = 1; p <= period; p++) {
                var o = this._roundOutcome(p, ch, st);
                integ = this._clamp(integ + o.integ);
                disc = this._clamp(disc + o.disc);
                air = this._clamp(air + o.air);
                pwinH.push(Math.round(st.pwin));
                evH.push(parseFloat(st.ev.toFixed(1)));
                scoreH.push(o.score);
                integH.push(Math.round(integ));
                discH.push(Math.round(disc));
                log.push({ period: p, score: o.score, nk: o.nk });
                last = o;
            }

            var total = 0;
            for (var s = 0; s < scoreH.length; s++) total += scoreH[s];
            ds.pwin = st.pwin; ds.netMargin = st.margin; ds.expectedValue = st.ev;
            ds.integrityScore = integ; ds.disciplineScore = disc; ds.airCover = air;
            ds.cumulativeScore = total;
            ds.pwinHistory = pwinH; ds.evHistory = evH; ds.scoreHistory = scoreH;
            ds.integrityHistory = integH; ds.disciplineHistory = discH; ds.decisionLog = log;

            var composite = this._composite(scoreH);
            ds.performance = { overallScore: composite };
            ds.performanceTier = this._band(composite);

            var out = {
                period: period,
                roundScore: last.score,
                pwin: Math.round(st.pwin),
                expectedValue: parseFloat(st.ev.toFixed(1)),
                integrityScore: Math.round(integ),
                disciplineScore: Math.round(disc),
                airCover: Math.round(air),
                carryOver: last.carry,
                nk: last.nk,
                ch: cur,
                overallScore: composite
            };
            this._paintFeedback(out);

            var self = this;
            var nextPeriod = period + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);
            return out;
        }

        _t() {
            return window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
        }

        _paintFeedback(res) {
            var box = document.getElementById('roundFeedback');
            if (!box) return;
            if (!res || !res.nk || !res.nk.length) {
                box.innerHTML = '';
                box.style.display = 'none';
                return;
            }
            var t = this._t();
            var html = '<div class="rfp-sim-feedback-title">' +
                t('fb_title').replace('{n}', res.period).replace('{s}', res.roundScore) + '</div>';
            for (var i = 0; i < res.nk.length; i++) {
                html += '<p class="rfp-sim-feedback-line">' + t(res.nk[i]) + '</p>';
            }
            box.innerHTML = html;
            box.style.display = 'block';
        }

        _renderFeedback(state) {
            var hist = (state && state.history) || [];
            var lastRec = hist.length ? hist[hist.length - 1] : null;
            this._paintFeedback(lastRec && lastRec.results ? lastRec.results : null);
        }

        _updateBriefing(state) {
            var t = this._t();
            var period = (state && state.currentPeriod) || 1;
            var panels = ['panelR1', 'panelR2', 'panelR3', 'panelR4'];
            var titleEl = document.getElementById('roundTitle');
            var settingEl = document.getElementById('roundSetting');
            var challengeEl = document.getElementById('roundChallenge');
            var row = document.querySelector('.rfp-sim-actions');
            var sb = document.getElementById('nextPeriodBtn');
            var c1El = document.getElementById('progressChart');
            var c2El = document.getElementById('disciplineChart');
            if (c1El) c1El.setAttribute('aria-label', t('chart1_alt'));
            if (c2El) c2El.setAttribute('aria-label', t('chart2_alt'));

            if (period > this.ROUNDS.length) {
                if (titleEl) titleEl.textContent = t('finished_title');
                if (settingEl) settingEl.textContent = t('finished_setting');
                if (challengeEl) challengeEl.textContent = t('finished_challenge');
                for (var n = 0; n < panels.length; n++) {
                    var hp = document.getElementById(panels[n]);
                    if (hp) hp.style.display = 'none';
                }
                if (row) row.style.display = 'none';
                if (sb) { sb.disabled = true; sb.setAttribute('aria-disabled', 'true'); }
                return;
            }
            if (row) row.style.display = '';
            if (sb && sb.getAttribute('aria-disabled') === 'true') {
                sb.disabled = false; sb.removeAttribute('aria-disabled');
            }

            var idx = period - 1;
            if (idx < 0) idx = 0;
            var round = this.ROUNDS[idx];
            var live = (state && state.domainState) ||
                (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var walked = live.bidPattern === 'D' && (period === 2 || period === 3);

            if (titleEl) titleEl.textContent = t(round.titleKey);
            if (settingEl) settingEl.textContent = t(round.settingKey);
            if (challengeEl) challengeEl.textContent = t(round.challengeKey) + (walked ? ' ' + t('walk_notice') : '');

            for (var i = 0; i < panels.length; i++) {
                var p = document.getElementById(panels[i]);
                if (p) p.style.display = (i === idx) ? 'grid' : 'none';
            }
            this._syncControlsFromDecisions(state);
        }

        _syncControlsFromDecisions(state) {
            var d = state && state.decisions;
            if (!d) return;
            var ids = {
                pattern: 'patternSelect', flipCondition: 'flipConditionSelect',
                tariff: 'tariffSelect', anchorTheme: 'themeSelect',
                integrityOption: 'integritySelect', monitor: 'monitorSelect',
                disclosure: 'disclosureSelect', gates: 'gatesSelect', escalation: 'escalationSelect'
            };
            for (var k in ids) {
                if (!Object.prototype.hasOwnProperty.call(ids, k)) continue;
                var el = document.getElementById(ids[k]);
                if (el && d[k] !== undefined && d[k] !== null) el.value = String(d[k]);
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('pwinDisplay', 'domainState.pwin', (v) => Math.round(v) + '%');
            uiManager.bind('evDisplay', 'domainState.expectedValue', (v) => 'USD ' + parseFloat(v).toFixed(1) + 'M');
            uiManager.bind('integrityDisplay', 'domainState.integrityScore', (v) => Math.round(v) + ' / 100');
            uiManager.bind('disciplineDisplay', 'domainState.disciplineScore', (v) => Math.round(v) + ' / 100');
            uiManager.bind('airCoverDisplay', 'domainState.airCover', (v) => Math.round(v) + ' / 100');
            uiManager.bind('cumulativeDisplay', 'domainState.cumulativeScore', (v) => Math.round(v) + ' pts');
        }

        getChartConfig() {
            return {
                progressChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'P(win) %',
                                data: [],
                                borderColor: '#1a3866',
                                backgroundColor: 'rgba(26,56,102,0.10)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Expected Value (USD M)',
                                data: [],
                                borderColor: '#c9a961',
                                backgroundColor: 'rgba(201,169,97,0.15)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Win Probability and Expected Value' } },
                        scales: {
                            y: { beginAtZero: true, position: 'left', title: { display: true, text: 'P(win) %' } },
                            y1: { beginAtZero: true, position: 'right', grid: { drawOnChartArea: false }, title: { display: true, text: 'EV USD M' } }
                        }
                    }
                },
                disciplineChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Integrity Score',
                                data: [],
                                backgroundColor: '#1a3866'
                            },
                            {
                                label: 'Discipline Score',
                                data: [],
                                backgroundColor: '#c9a961'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
