                        plugins: { title: { display: true, text: 'Integrity and Discipline Scores' } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var pw = ds.pwinHistory || [];
            var labels = pw.map(function(_, i) { return 'R' + (i + 1); });
            return {
                progressChart: {
                    labels: labels,
                    datasets: [
                        { data: pw },
                        { data: ds.evHistory || [] }
                    ]
                },
                disciplineChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.integrityHistory || [] },
                        { data: ds.disciplineHistory || [] }
                    ]
                }
            };
        }

        _mistakes(history) {
            var byP = {};
            for (var i = 0; i < history.length; i++) {
                var r = history[i] && history[i].results;
                if (r && r.period) byP[r.period] = r;
            }
            var c1 = (byP[1] && byP[1].ch) || {};
            var c2 = (byP[2] && byP[2].ch) || {};
            var c3 = (byP[3] && byP[3].ch) || {};
            var c4 = (byP[4] && byP[4].ch) || {};
            var walked = c1.pattern === 'D';
            var found = [];
            if (byP[1] && (!c1.flipCondition || c1.flipCondition === 'none')) {
                found.push({ key: 'dbf_m1', round: 1, cost: 30 + (byP[4] ? 16 : 0) });
            }
            if (byP[2] && !walked && c2.tariff === 'aggressive') {
                found.push({ key: 'dbf_m2', round: 2, cost: 26 + (byP[3] ? 16 : 0) });
            }
            if (byP[3] && !walked) {
                var reversal = c3.integrityOption !== c1.pattern;
                if (reversal) {
                    var gap = { A: 0, B: 8, C: 12, D: 14 }[c3.integrityOption] || 0;
                    found.push({ key: (c3.integrityOption === 'A' ? 'dbf_m4a' : 'dbf_m4'), round: 3, cost: 24 + gap + (byP[4] ? 16 : 0) });
                }
                if (c3.integrityOption !== 'D' && (c3.monitor !== 'thirdparty' || c3.disclosure !== 'full')) {
                    var mLoss = { thirdparty: 0, internal: 40, none: 62 }[c3.monitor];
                    var dLoss = { full: 0, partial: 18, none: 38 }[c3.disclosure];
                    found.push({ key: 'dbf_m3', round: 3, cost: (mLoss || 0) + (dLoss || 0) });
                }
            }
            if (byP[4]) {
                if (c4.gates === '1') found.push({ key: 'dbf_m5', round: 4, cost: 40 });
                if (c4.escalation !== 'audit') {
                    found.push({ key: 'dbf_m5e', round: 4, cost: c4.escalation === 'ceo' ? 24 : 36 });
                }
            }
            found.sort(function(a, b) { return (b.cost - a.cost) || (a.round - b.round); });
            return found;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var t = window.mySimulation.t.bind(window.mySimulation);
            var total = 0;
            var scores = [];
            var low = null;
            for (var i = 0; i < history.length; i++) {
                var rs = (history[i].results && history[i].results.roundScore) || 0;
                total += rs;
                scores.push(rs);
                if (low === null || rs < low.s) low = { n: i + 1, s: rs };
            }
            var composite = this._composite(scores);
            var band = this._band(composite);
            var last = history[history.length - 1].results || {};
            var found = this._mistakes(history);

            var turning;
            if (found.length) {
                turning = t(found[0].key).replace('{pts}', found[0].cost);
            } else {
                turning = t('dbf_tp_none').replace('{n}', low.n).replace('{s}', low.s);
            }

            var insights = [];
            insights.push(t('sum_points').replace('{pts}', Math.round(total)).replace('{max}', this.ROUNDS.length * 100));
            insights.push(t('sum_' + band));
            for (var m = 1; m < found.length && m < 3; m++) {
                insights.push(t(found[m].key).replace('{pts}', found[m].cost));
            }
            if (insights.length < 5) insights.push(t('sum_codify'));

            return {
                totalPoints: Math.round(total),
                avgScore: composite,
                overallScore: composite,
                totalScore: composite,
                composite: composite,
                score: composite,
                performance: band,
                performanceKey: band,
                performanceLabel: t('band_' + band),
                turningPoint: turning,
                outcome: { pwin: last.pwin, expectedValue: last.expectedValue },
                process: { integrity: last.integrityScore, discipline: last.disciplineScore, airCover: last.airCover },
                insights: insights,
                questions: [t('dbf_q1'), t('dbf_q2')]
            };
        }

        formatCompletionMessage(summary) {
            var t = window.mySimulation.t.bind(window.mySimulation);
            var s = summary || {};
            var band = s.performanceKey || s.performance || 'beginner';
            var html = '<div class="rfp-sim-completion">';
            html += '<h3 class="rfp-sim-completion-title">' + t('completion_title') + '</h3>';
            html += '<p class="rfp-sim-completion-score"><strong>' + t('completion_score_label') + '</strong> ' +
                    (s.overallScore || 0) + ' / 100 &mdash; ' + (s.performanceLabel || t('band_' + band)) + '</p>';
            var oc = s.outcome || {};
            var pr = s.process || {};
            if (oc.pwin !== undefined && pr.integrity !== undefined) {
                html += '<p class="rfp-sim-completion-sub"><strong>' + t('dbf_outcome') + '</strong> ' +
                    t('pwin_label') + ' ' + oc.pwin + '% · ' + t('ev_label') + ' USD ' + parseFloat(oc.expectedValue).toFixed(1) + 'M</p>';
                html += '<p class="rfp-sim-completion-sub"><strong>' + t('dbf_process') + '</strong> ' +
                    t('integrity_label') + ' ' + pr.integrity + ' · ' + t('discipline_label') + ' ' + pr.discipline +
                    ' · ' + t('aircover_label') + ' ' + pr.airCover + '</p>';
            }
            if (s.turningPoint) {
                html += '<p class="rfp-sim-completion-turn"><strong>' + t('dbf_turning') + '</strong> ' + s.turningPoint + '</p>';
            }
            var ins = s.insights || [];
            if (ins.length) {
                html += '<ul class="rfp-sim-completion-insights">';
                for (var i = 0; i < ins.length; i++) html += '<li>' + ins[i] + '</li>';
                html += '</ul>';
            }
            var qs = s.questions || [];
            if (qs.length) {
                html += '<p class="rfp-sim-completion-sub"><strong>' + t('dbf_questions') + '</strong></p>';
                html += '<ol class="rfp-sim-completion-questions">';
                for (var j = 0; j < qs.length; j++) html += '<li>' + qs[j] + '</li>';
                html += '</ol>';
            }
            html += '</div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (state.domainState.bidPattern === 'D' && state.currentPeriod >= 2) {
                return window.mySimulation.t('hint_walked');
            }
            if (results.integrityScore < 50) {
                return window.mySimulation.t('hint_integrity_low');
            }
            if (results.roundScore < 50) {
                return window.mySimulation.t('hint_low_score');
            }
            if (state.domainState.airCover < 30 && state.currentPeriod >= 3) {
                return window.mySimulation.t('hint_air_cover');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.roundScore', label: 'Decision Quality', i18nKey: 'col_score', formatter: (v) => v + ' / 100' },
                { key: 'results.pwin', label: 'P(win)', i18nKey: 'col_pwin', formatter: (v) => v + '%' },
                { key: 'results.expectedValue', label: 'EV (USD M)', i18nKey: 'col_ev', formatter: (v) => 'USD ' + parseFloat(v).toFixed(1) + 'M' },
                { key: 'results.integrityScore', label: 'Integrity', i18nKey: 'col_integrity' },
